#!/usr/bin/env python3

"""Comprehensive test for infl of template variants."""

from wikidict.render import parse_word

# Test various infl of template formats
test_cases = [
    # Basic case from the issue
    {
        "word": "clinging",
        "content": """==English==
===Verb===
{{en-verb}}
# {{infl of|en|cling||ing-form}}
""",
        "expected_variants": ["cling"]
    },

    # Different form
    {
        "word": "clung",
        "content": """==English==
===Verb===
{{en-verb}}
# {{infl of|en|cling||past}}
""",
        "expected_variants": ["cling"]
    },

    # With additional parameters
    {
        "word": "clings", 
        "content": """==English==
===Verb===
{{en-verb}}
# {{infl of|en|cling|t=third-person singular}}
""",
        "expected_variants": ["cling"]
    }
]

print("Running comprehensive tests...")
all_passed = True

for i, test_case in enumerate(test_cases, 1):
    print(f"\nTest {i}: {test_case['word']}")
    try:
        details = parse_word(test_case["word"], test_case["content"], "en", force=True)
        actual_variants = sorted(details.variants)
        expected_variants = sorted(test_case["expected_variants"])

        print(f"  Expected variants: {expected_variants}")
        print(f"  Actual variants:   {actual_variants}")

        if actual_variants == expected_variants:
            print("  ✓ PASS")
        else:
            print("  ✗ FAIL")
            all_passed = False

    except Exception as e:
        print(f"  ✗ ERROR: {e}")
        all_passed = False

print(f"\nOverall result: {'PASS' if all_passed else 'FAIL'}")
